using System.Collections.ObjectModel;using System.ComponentModel;using System.Runtime.CompilerServices;using Biblia.Application.Interfaces;using Biblia.Domain.Entities;using Biblia.Presentation.Commands;namespace Biblia.Presentation.ViewModels;public sealed class GlobalSearchViewModel:INotifyPropertyChanged,IDisposable{private readonly IGlobalSearchService _service;private CancellationTokenSource? _searchCancellation;private string _text="",_status="";private bool _busy;public GlobalSearchViewModel(IGlobalSearchService service){_service=service;SearchCommand=new AsyncCommand(SearchAsync,()=>!IsBusy&&Text.Trim().Length>=2);ClearCommand=new AsyncCommand(ClearAsync,()=>!IsBusy);}public ObservableCollection<GlobalSearchResult> Items{get;}=[];public string Text{get=>_text;set{if(Set(ref _text,value))SearchCommand.NotifyCanExecuteChanged();}}public string Status{get=>_status;private set=>Set(ref _status,value);}public bool IsBusy{get=>_busy;private set{if(Set(ref _busy,value)){SearchCommand.NotifyCanExecuteChanged();ClearCommand.NotifyCanExecuteChanged();}}}public AsyncCommand SearchCommand{get;}public AsyncCommand ClearCommand{get;}public event PropertyChangedEventHandler? PropertyChanged;private async Task SearchAsync(){_searchCancellation?.Cancel();var cancellation=new CancellationTokenSource();_searchCancellation=cancellation;IsBusy=true;try{var found=await _service.SearchAsync(Text,cancellationToken:cancellation.Token);if(cancellation.IsCancellationRequested)return;Items.Clear();foreach(var item in found)Items.Add(item);Status=Items.Count==0?"Nenhum resultado encontrado.":$"{Items.Count} resultado(s) em múltiplos domínios.";}catch(OperationCanceledException){}catch{Status="Não foi possível concluir a pesquisa global.";}finally{if(ReferenceEquals(_searchCancellation,cancellation)){IsBusy=false;_searchCancellation=null;}cancellation.Dispose();}}private Task ClearAsync(){_searchCancellation?.Cancel();Text="";Items.Clear();Status="Pesquisa limpa.";return Task.CompletedTask;}public void Dispose(){_searchCancellation?.Cancel();_searchCancellation?.Dispose();}private bool Set<T>(ref T f,T v,[CallerMemberName]string?n=null){if(EqualityComparer<T>.Default.Equals(f,v))return false;f=v;PropertyChanged?.Invoke(this,new(n));return true;}}
